import sqlparse
from sqlparse.sql import Identifier
p = sqlparse.parse('SELECT db.schema.tbl.col AS x FROM t')[0]
for tok in p.tokens:
    if tok.ttype is None:
        print(type(tok).__name__, repr(tok.value))
        for x in tok.tokens:
            if isinstance(x, Identifier):
                print('   ', repr(x.value), 'real:', repr(x.get_real_name()), 'alias:', repr(x.get_alias()))
